# Recipe Book, version 3: one shopping list for many recipes
SERVES = 2  # every card in the book feeds 2 people
book = {
    "pancakes": {"flour (g)": 200, "milk (ml)": 300,
                 "eggs": 2, "honey (tbsp)": 2},
    "tomato soup": {"tomatoes": 6, "onion": 1, "milk (ml)": 100},
    "fruit salad": {"apples": 2, "bananas": 2, "honey (tbsp)": 1},
}

def nice(x):
    if x == int(x):
        return str(int(x))
    return f"{x:.1f}"

def scale(amount, guests):
    return amount * guests / SERVES

def show_recipe(book, name, guests):
    print(f"--- {name} for {guests} ---")
    for item, amount in book[name].items():
        print(f"  {item}: {nice(scale(amount, guests))}")

def shopping_list(book, names, guests):
    totals = {}
    for name in names:
        for item, amount in book[name].items():
            if item not in totals:
                totals[item] = 0
            totals[item] += scale(amount, guests)
    return totals

print("PIP'S RECIPE BOOK")
