SERVES = 2  # every card in the book feeds 2 people

def nice(x):
    if x == int(x):
        return str(int(x))
    return f"{x:.1f}"

def scale(amount, guests):
    return amount * guests / SERVES

def show_recipe(book, name, guests):
    print(f"--- {name} for {guests} ---")
    for item, amount in book[name].items():
        print(f"  {item}: {nice(scale(amount, guests))}")

def shopping_list(book, names, guests):
